//! Differential ratchet for src/engine/battleScriptGender.ts.
//! Expected outputs are generated by executing the canonical TypeScript
//! resolver; regenerate with node --experimental-strip-types
//! core-rs/tools/gen-battle-script-gender-vectors.mjs.

use std::collections::BTreeSet;

use factory_core::battle_script_gender::resolve_battle_script_mon_gender;
use factory_core::battle_script_gender_vectors_gen::{
    BATTLE_SCRIPT_GENDER_BRANCH_CENSUS, BATTLE_SCRIPT_GENDER_CASES,
    BATTLE_SCRIPT_GENDER_CATEGORY_CENSUS, BATTLE_SCRIPT_GENDER_DOMAIN_CENSUS,
    BATTLE_SCRIPT_GENDER_SPECIES_DOMAIN, BATTLE_SCRIPT_GENDER_VECTOR_CORPUS_SHA256,
};
use factory_core::species_gender_ratios_gen::species_gender_ratio;

#[test]
fn canonical_typescript_outputs_cover_every_species_and_missing_id() {
    let mut canonical_species = BTreeSet::new();

    for (index, case) in BATTLE_SCRIPT_GENDER_CASES.iter().enumerate() {
        let result = resolve_battle_script_mon_gender(case.species, case.personality);
        match (case.gender_ratio, case.expected_gender, case.expected_error) {
            (Some(expected_ratio), Some(expected_gender), None) => {
                canonical_species.insert(case.species);
                let generated_ratio = species_gender_ratio(case.species).unwrap_or_else(|| {
                    panic!(
                        "case {index} {}: canonical species absent from generated table",
                        case.label
                    )
                });
                assert_eq!(
                    generated_ratio, expected_ratio,
                    "case {index} {}: generated table gender ratio",
                    case.label,
                );
                assert_eq!(
                    result.unwrap_or_else(|error| {
                        panic!("case {index} {}: unexpected error {error}", case.label)
                    }),
                    expected_gender,
                    "case {index} {}: resolved gender",
                    case.label,
                );
            }
            (None, None, Some(expected_error)) => {
                assert!(
                    species_gender_ratio(case.species).is_none(),
                    "case {index} {}: missing-id vector unexpectedly exists in generated table",
                    case.label,
                );
                assert_eq!(
                    result.unwrap_err().to_string(),
                    expected_error,
                    "case {index} {}: exact missing-id error",
                    case.label,
                );
            }
            _ => panic!(
                "case {index} {}: generator emitted an invalid outcome shape",
                case.label
            ),
        }
    }

    assert_eq!(
        canonical_species.into_iter().collect::<Vec<_>>(),
        BATTLE_SCRIPT_GENDER_SPECIES_DOMAIN,
        "every canonical TypeScript species row must appear in the corpus",
    );
}

#[test]
fn domain_category_branch_censuses_and_corpus_hash_are_ratchet_pinned() {
    assert_eq!(BATTLE_SCRIPT_GENDER_SPECIES_DOMAIN.len(), 411);
    assert_eq!(BATTLE_SCRIPT_GENDER_SPECIES_DOMAIN[0], 1);
    assert_eq!(BATTLE_SCRIPT_GENDER_SPECIES_DOMAIN[410], 411);
    assert_eq!(
        BATTLE_SCRIPT_GENDER_DOMAIN_CENSUS,
        [
            ("canonical-species", 411),
            ("missing-species-ids", 3),
            ("personality-u32-edges-per-canonical-species", 2),
        ],
    );
    assert_eq!(BATTLE_SCRIPT_GENDER_CASES.len(), 2306);
    assert_eq!(
        BATTLE_SCRIPT_GENDER_CATEGORY_CENSUS,
        [
            ("always-female", 44),
            ("always-male", 40),
            ("genderless", 248),
            ("missing-species", 6),
            ("mixed-low-byte-boundary", 1968),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_GENDER_BRANCH_CENSUS,
        [
            ("fixed-female", 44),
            ("fixed-genderless", 248),
            ("fixed-male", 40),
            ("species-lookup-error", 6),
            ("threshold-female", 984),
            ("threshold-male", 984),
        ],
    );
    assert_eq!(
        BATTLE_SCRIPT_GENDER_VECTOR_CORPUS_SHA256,
        "bb2aaff65e2c88fa5074fbd544be1cba6be22bdbad75e91259f03af752576edc",
    );
}
